// Diagnostic only: observe native transitions; original readiness and assertions remain exact.
async function p01NativeResizeProbe(page: Page, info: TestInfo) {
  const frame = page.frameLocator('iframe')
  await frame.locator('body').evaluate(() => {
    const w = window as any, ui = w.__p01Ui, g = ui.editor.graph, records: unknown[] = []
    let overflow = false
    const sample = (kind: string, stack = false) => {
      if (records.length >= 4096) { overflow = true; return }
      const box = (node: HTMLElement) => { const b = node.getBoundingClientRect(); return { x: b.x, y: b.y, width: b.width, height: b.height } }
      const sidebar = ui.sidebarContainer as HTMLElement, style = getComputedStyle(sidebar)
      records.push({ kind, at: performance.now(), view: [g.view.scale, g.view.translate.x, g.view.translate.y], viewport: [innerWidth, innerHeight], lastWindowWidth: ui.lastWindowWidth, hsplit: ui.hsplitPosition, graph: box(g.container), sidebar: { box: box(sidebar), inline: sidebar.getAttribute('style'), transform: style.transform, transition: style.transition }, focused: document.hasFocus(), stack: stack ? new Error('Observed original native view event').stack : undefined })
    }
    const viewListener = () => sample('view', true), shapesListener = () => sample('shapesPanelChanged'), resizeListener = () => sample('window.resize')
    for (const name of ['scale', 'translate', 'scaleAndTranslate']) g.view.addListener(name, viewListener)
    ui.addListener('shapesPanelChanged', shapesListener); window.addEventListener('resize', resizeListener)
    const observer = new MutationObserver(() => sample('sidebar.style'))
    observer.observe(ui.sidebarContainer, { attributes: true, attributeFilter: ['style'] }); sample('armed')
    w.__p01NativeResizeProbe = () => {
      sample('finish'); observer.disconnect(); g.view.removeListener(viewListener); ui.removeListener(shapesListener); window.removeEventListener('resize', resizeListener); delete w.__p01NativeResizeProbe
      return { records, overflow, cleanup: true, readinessAndAssertionsChanged: false }
    }
  })
  return async () => {
    const result = await frame.locator('body').evaluate(() => (window as any).__p01NativeResizeProbe())
    await writeFile(info.outputPath('native-resize-diagnostic.json'), JSON.stringify(result, null, 2))
    if (result.overflow) throw Error('Native diagnostic record limit exceeded')
  }
}
